// PlanB64: compile bounded IPv6 longest-prefix matches into an interval image.
#include <arpa/inet.h>

#include <algorithm>
#include <array>
#include <cerrno>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <fcntl.h>
#include <fstream>
#include <iostream>
#include <iterator>
#include <limits>
#include <stdexcept>
#include <string>
#include <string_view>
#include <unistd.h>
#include <vector>

namespace {

constexpr std::size_t kMaxFibRecords = 200000;
constexpr std::size_t kMaxTraceRecords = 1000000;
constexpr std::size_t kMaxImageRows = 400001;
constexpr std::size_t kMaxTextLine = 256;
constexpr uint64_t kMaxKey = std::numeric_limits<uint64_t>::max();

struct Row {
    uint64_t start;
    int64_t hop;
    int length;
};

struct Route {
    uint64_t start;
    uint64_t end;
    uint32_t hop;
    int length;
};

struct Event {
    uint64_t key;
    uint32_t route;
    bool addition;
};

[[noreturn]] void fail(const char* message) {
    throw std::runtime_error(message);
}

bool record_space(char c) {
    return c == ' ' || c == '\t' || c == '\r';
}

std::vector<std::string_view> fields(const std::string& line) {
    std::vector<std::string_view> result;
    std::size_t pos = 0;
    while (pos < line.size()) {
        while (pos < line.size() && record_space(line[pos])) ++pos;
        if (pos == line.size()) break;
        const std::size_t begin = pos;
        while (pos < line.size() && !record_space(line[pos])) ++pos;
        result.emplace_back(line.data() + begin, pos - begin);
    }
    return result;
}

template <typename UInt>
UInt decimal_value(std::string_view text, UInt maximum, bool canonical = false) {
    static_assert(std::is_unsigned<UInt>::value, "unsigned type required");
    if (text.empty()) fail("empty decimal field");
    if (canonical && text.size() > 1 && text.front() == '0')
        fail("noncanonical decimal field");
    UInt value = 0;
    for (char c : text) {
        if (c < '0' || c > '9') fail("invalid decimal field");
        const unsigned digit = static_cast<unsigned>(c - '0');
        if (value > static_cast<UInt>((maximum - static_cast<UInt>(digit)) /
                                      static_cast<UInt>(10)))
            fail("decimal field out of range");
        value = static_cast<UInt>(value * static_cast<UInt>(10) +
                                  static_cast<UInt>(digit));
    }
    return value;
}

// This overload handles values whose upper bound is smaller than the integer
// type used while accumulating, without allowing intermediate overflow.
uint64_t bounded_decimal(std::string_view text, uint64_t maximum,
                         bool canonical = false) {
    if (text.empty()) fail("empty decimal field");
    if (canonical && text.size() > 1 && text.front() == '0')
        fail("noncanonical decimal field");
    uint64_t value = 0;
    for (char c : text) {
        if (c < '0' || c > '9') fail("invalid decimal field");
        const uint64_t digit = static_cast<uint64_t>(c - '0');
        if (value > maximum / 10 ||
            (value == maximum / 10 && digit > maximum % 10))
            fail("decimal field out of range");
        value = value * 10 + digit;
    }
    return value;
}

std::ifstream open_input(const char* path) {
    std::ifstream input(path, std::ios::binary);
    if (!input.is_open()) fail("cannot open input file");
    return input;
}

void check_text_line(const std::string& line) {
    if (line.size() > kMaxTextLine) fail("input line is too long");
    for (unsigned char c : line) {
        if (c == 0 || c > 127) fail("input is not ASCII text");
    }
}

template <typename Callback>
void read_text_records(const char* path, Callback&& callback) {
    auto input = open_input(path);
    std::string line;
    while (std::getline(input, line)) {
        check_text_line(line);
        auto tokens = fields(line);
        if (!tokens.empty()) callback(tokens);
    }
    if (input.bad()) fail("cannot read input file");
}

uint64_t address_key(std::string_view text) {
    if (text.empty() || text.find('\0') != std::string_view::npos)
        fail("invalid IPv6 address");
    // inet_pton expects a terminated string.  Input lines are bounded, so this
    // small copy also ensures that no embedded NUL can hide trailing text.
    std::string address(text);
    std::array<unsigned char, 16> bytes{};
    if (::inet_pton(AF_INET6, address.c_str(), bytes.data()) != 1)
        fail("invalid IPv6 address");
    uint64_t key = 0;
    for (std::size_t i = 0; i < 8; ++i)
        key = (key << 8) | static_cast<uint64_t>(bytes[i]);
    return key;
}

Route make_route(std::string_view prefix, std::string_view hop_text) {
    const std::size_t slash = prefix.find('/');
    if (slash == std::string_view::npos || slash == 0 ||
        slash + 1 == prefix.size())
        fail("invalid FIB prefix");
    const uint64_t key = address_key(prefix.substr(0, slash));
    const int length = static_cast<int>(
        bounded_decimal(prefix.substr(slash + 1), 64));
    const uint64_t hop64 = bounded_decimal(
        hop_text, std::numeric_limits<uint32_t>::max());

    const uint64_t mask = length == 0 ? uint64_t{0}
                                     : kMaxKey << (64 - length);
    const uint64_t start = key & mask;
    const uint64_t end = start | ~mask;
    return Route{start, end, static_cast<uint32_t>(hop64), length};
}

bool same_pair(const Row& row, int64_t hop, int length) {
    return row.hop == hop && row.length == length;
}

std::vector<Row> compile_fib(const char* path) {
    std::vector<Route> routes;
    read_text_records(path, [&](const std::vector<std::string_view>& tokens) {
        if (tokens.size() != 2) fail("invalid FIB record");
        if (routes.size() == kMaxFibRecords) fail("too many FIB records");
        routes.push_back(make_route(tokens[0], tokens[1]));
    });

    std::sort(routes.begin(), routes.end(), [](const Route& a, const Route& b) {
        if (a.length != b.length) return a.length < b.length;
        return a.start < b.start;
    });
    for (std::size_t i = 1; i < routes.size(); ++i) {
        if (routes[i - 1].length == routes[i].length &&
            routes[i - 1].start == routes[i].start)
            fail("duplicate normalized FIB prefix");
    }

    std::vector<Event> events;
    events.reserve(routes.size() * 2);
    for (std::size_t i = 0; i < routes.size(); ++i) {
        events.push_back(Event{routes[i].start, static_cast<uint32_t>(i), true});
        if (routes[i].end != kMaxKey)
            events.push_back(
                Event{routes[i].end + 1, static_cast<uint32_t>(i), false});
    }
    std::sort(events.begin(), events.end(), [](const Event& a, const Event& b) {
        return a.key < b.key;
    });

    // At most one route of each length can be active: equal-length IPv6
    // prefixes are disjoint.  Removals precede additions at shared endpoints.
    std::array<int64_t, 65> active{};
    active.fill(-1);
    std::vector<Row> rows;
    rows.reserve(events.size() + 1);
    rows.push_back(Row{0, -1, -1});

    std::size_t pos = 0;
    while (pos < events.size()) {
        const uint64_t key = events[pos].key;
        std::size_t end = pos;
        while (end < events.size() && events[end].key == key) ++end;
        for (std::size_t i = pos; i < end; ++i) {
            if (!events[i].addition)
                active[routes[events[i].route].length] = -1;
        }
        for (std::size_t i = pos; i < end; ++i) {
            if (events[i].addition) {
                const Route& route = routes[events[i].route];
                if (active[route.length] != -1) fail("overlapping equal-length routes");
                active[route.length] = route.hop;
            }
        }

        int64_t hop = -1;
        int length = -1;
        for (int candidate = 64; candidate >= 0; --candidate) {
            if (active[candidate] != -1) {
                hop = active[candidate];
                length = candidate;
                break;
            }
        }
        if (!same_pair(rows.back(), hop, length)) {
            if (key == 0)
                rows.back() = Row{0, hop, length};
            else
                rows.push_back(Row{key, hop, length});
        }
        pos = end;
    }
    if (rows.empty() || rows.size() > kMaxImageRows)
        fail("compiled image has an invalid row count");
    return rows;
}

void append_hex16(std::string& output, uint64_t value) {
    static constexpr char digits[] = "0123456789abcdef";
    char encoded[16];
    for (int i = 15; i >= 0; --i) {
        encoded[i] = digits[value & 0xf];
        value >>= 4;
    }
    output.append(encoded, sizeof(encoded));
}

std::string serialize_image(const std::vector<Row>& rows) {
    std::string output;
    output.reserve(32 + rows.size() * 32);
    output += "PLANB64 1\n";
    output += std::to_string(rows.size());
    output.push_back('\n');
    for (const Row& row : rows) {
        append_hex16(output, row.start);
        output.push_back(' ');
        output += std::to_string(row.hop);
        output.push_back(' ');
        output += std::to_string(row.length);
        output.push_back('\n');
    }
    return output;
}

void write_all(int fd, const std::string& data) {
    std::size_t pos = 0;
    while (pos < data.size()) {
        const ssize_t written = ::write(fd, data.data() + pos, data.size() - pos);
        if (written < 0) {
            if (errno == EINTR) continue;
            fail("cannot write image file");
        }
        if (written == 0) fail("cannot write image file");
        pos += static_cast<std::size_t>(written);
    }
}

void save_image_atomic(const char* destination, const std::string& data) {
    const std::string path(destination);
    const std::size_t slash = path.find_last_of('/');
    const std::string directory =
        slash == std::string::npos ? "." : (slash == 0 ? "/" : path.substr(0, slash));
    int fd = -1;
    std::string temporary;
    for (unsigned attempt = 0; attempt < 100 && fd < 0; ++attempt) {
        temporary = directory;
        if (temporary.empty() || temporary.back() != '/') temporary.push_back('/');
        temporary += ".planb64.tmp." + std::to_string(static_cast<long long>(::getpid())) +
                     "." + std::to_string(attempt);
        fd = ::open(temporary.c_str(), O_WRONLY | O_CREAT | O_EXCL, 0666);
        if (fd < 0 && errno != EEXIST) fail("cannot create image file");
    }
    if (fd < 0) fail("cannot create image file");

    try {
        write_all(fd, data);
        if (::close(fd) != 0) {
            fd = -1;
            fail("cannot close image file");
        }
        fd = -1;
        if (::rename(temporary.c_str(), path.c_str()) != 0)
            fail("cannot install image file");
    } catch (...) {
        if (fd >= 0) ::close(fd);
        ::unlink(temporary.c_str());
        throw;
    }
}

std::string read_whole_file(const char* path) {
    auto input = open_input(path);
    std::string data((std::istreambuf_iterator<char>(input)),
                     std::istreambuf_iterator<char>());
    if (input.bad()) fail("cannot read image file");
    return data;
}

std::string_view image_line(const std::string& data, std::size_t& pos) {
    if (pos >= data.size()) fail("missing image record");
    const std::size_t newline = data.find('\n', pos);
    if (newline == std::string::npos) fail("image lacks final newline");
    const std::string_view line(data.data() + pos, newline - pos);
    pos = newline + 1;
    return line;
}

uint64_t hex_key(std::string_view text) {
    if (text.size() != 16) fail("invalid image key");
    uint64_t key = 0;
    for (char c : text) {
        unsigned digit;
        if (c >= '0' && c <= '9')
            digit = static_cast<unsigned>(c - '0');
        else if (c >= 'a' && c <= 'f')
            digit = static_cast<unsigned>(c - 'a') + 10;
        else
            fail("invalid image key");
        key = (key << 4) | static_cast<uint64_t>(digit);
    }
    return key;
}

std::vector<Row> load_image(const char* path) {
    const std::string data = read_whole_file(path);
    if (data.empty() || data.back() != '\n') fail("image lacks final newline");
    std::size_t pos = 0;
    if (image_line(data, pos) != "PLANB64 1") fail("invalid image header");
    const uint64_t count64 = bounded_decimal(image_line(data, pos), kMaxImageRows, true);
    if (count64 == 0) fail("invalid image row count");
    const std::size_t count = static_cast<std::size_t>(count64);

    std::vector<Row> rows;
    rows.reserve(count);
    for (std::size_t i = 0; i < count; ++i) {
        const std::string_view line = image_line(data, pos);
        if (line.size() < 20 || line[16] != ' ') fail("invalid image row");
        const uint64_t key = hex_key(line.substr(0, 16));
        const std::size_t separator = line.find(' ', 17);
        if (separator == std::string_view::npos || separator == 17 ||
            separator + 1 == line.size() ||
            line.find(' ', separator + 1) != std::string_view::npos)
            fail("invalid image row");
        const std::string_view hop_text = line.substr(17, separator - 17);
        const std::string_view length_text = line.substr(separator + 1);

        int64_t hop;
        int length;
        if (hop_text == "-1" || length_text == "-1") {
            if (hop_text != "-1" || length_text != "-1")
                fail("one-sided no-match image pair");
            hop = -1;
            length = -1;
        } else {
            hop = static_cast<int64_t>(bounded_decimal(
                hop_text, std::numeric_limits<uint32_t>::max(), true));
            length = static_cast<int>(bounded_decimal(length_text, 64, true));
        }
        if (i == 0) {
            if (key != 0) fail("first image key is not zero");
        } else {
            if (key <= rows.back().start) fail("unordered image keys");
            if (rows.back().hop == hop && rows.back().length == length)
                fail("redundant image row");
        }
        rows.push_back(Row{key, hop, length});
    }
    if (pos != data.size()) fail("image row count mismatch or extra data");
    return rows;
}

std::vector<uint64_t> load_trace(const char* path) {
    std::vector<uint64_t> queries;
    read_text_records(path, [&](const std::vector<std::string_view>& tokens) {
        if (tokens.size() != 1) fail("invalid trace record");
        if (queries.size() == kMaxTraceRecords) fail("too many trace records");
        queries.push_back(address_key(tokens[0]));
    });
    return queries;
}

const Row& predecessor(const std::vector<Row>& rows, uint64_t key) {
    const auto it = std::upper_bound(
        rows.begin(), rows.end(), key,
        [](uint64_t value, const Row& row) { return value < row.start; });
    // A validated image always starts at zero, so it is never rows.begin().
    return *--it;
}

std::size_t batch_size(const char* text) {
    const std::string_view value(text);
    if (value.empty()) fail("invalid batch size");
    std::size_t result = 0;
    for (char c : value) {
        if (c < '0' || c > '9') fail("invalid batch size");
        const unsigned digit = static_cast<unsigned>(c - '0');
        if (result > 256 || (result == 256 && digit != 0))
            fail("invalid batch size");
        result = result * 10 + digit;
        if (result > 256) fail("invalid batch size");
    }
    if (result == 0) fail("invalid batch size");
    return result;
}

void run_lookup(const char* image_path, const char* trace_path,
                const char* output_data, std::size_t output_size) {
    const std::vector<Row> rows = load_image(image_path);
    const std::vector<uint64_t> queries = load_trace(trace_path);
    (void)output_data;
    (void)output_size;

    std::string output;
    output.reserve(queries.size() * 8);
    for (uint64_t query : queries) {
        const Row& row = predecessor(rows, query);
        output += std::to_string(row.hop);
        output.push_back(' ');
        output += std::to_string(row.length);
        output.push_back('\n');
    }
    std::cout.write(output.data(), static_cast<std::streamsize>(output.size()));
    std::cout.flush();
    if (!std::cout) fail("cannot write lookup output");
}

}  // namespace

int main(int argc, char** argv) {
    try {
        if (argc == 4 && std::string_view(argv[1]) == "build") {
            const std::vector<Row> rows = compile_fib(argv[2]);
            save_image_atomic(argv[3], serialize_image(rows));
            return 0;
        }
        if (argc == 5 && std::string_view(argv[1]) == "lookup" &&
            std::string_view(argv[4]) == "scalar") {
            run_lookup(argv[2], argv[3], nullptr, 0);
            return 0;
        }
        if (argc == 6 && std::string_view(argv[1]) == "lookup" &&
            std::string_view(argv[4]) == "batch") {
            const std::size_t size = batch_size(argv[5]);
            // The interface is batched even though both modes share the same
            // predecessor implementation.  Validate the size before any I/O;
            // processing below retains every final partial batch.
            const std::vector<Row> rows = load_image(argv[2]);
            const std::vector<uint64_t> queries = load_trace(argv[3]);
            std::string output;
            output.reserve(queries.size() * 8);
            for (std::size_t base = 0; base < queries.size(); base += size) {
                const std::size_t end = std::min(base + size, queries.size());
                for (std::size_t i = base; i < end; ++i) {
                    const Row& row = predecessor(rows, queries[i]);
                    output += std::to_string(row.hop);
                    output.push_back(' ');
                    output += std::to_string(row.length);
                    output.push_back('\n');
                }
            }
            std::cout.write(output.data(), static_cast<std::streamsize>(output.size()));
            std::cout.flush();
            if (!std::cout) fail("cannot write lookup output");
            return 0;
        }
        fail("invalid arguments");
    } catch (const std::exception& error) {
        std::cerr << "ERROR: " << error.what() << '\n';
        return 2;
    } catch (...) {
        std::cerr << "ERROR: unknown failure\n";
        return 2;
    }
}
